//action
function handleShiftSpectrumAlongXAxis(draft, action) {
    const activeSpectrum = getActiveSpectrum(draft);
    if (!activeSpectrum)
        return;
    const activeFilterIndex = getActiveFilterIndex(draft);
    //apply filter into the spectrum
    const options = action.payload;
    const index = activeSpectrum.index;
    const isOneDimensionSpectrum = isSpectrum1D(draft.data[index]);
    const isOneDimensionShiftFilter = isOneDimensionShift(options);
    if (isOneDimensionShiftFilter && isOneDimensionSpectrum) {
        const { shift } = options;
        rollbackSpectrumByFilter(draft, {
            key: 'shiftX',
            searchBy: 'name',
            applyFilter: false,
        });
        Filters1DManager.applyFilters(draft.data[index], [{ name: 'shiftX', value: { shift } }], {
            filterIndex: activeFilterIndex,
            forceReapply: activeFilterIndex !== -1,
        });
        updateView(draft, shiftX.domainUpdateRules);
    }
    if (!isOneDimensionShiftFilter && !isOneDimensionSpectrum) {
        const { shiftX, shiftY } = options;
        if (shiftX) {
            rollbackSpectrumByFilter(draft, {
                key: 'shift2DX',
                searchBy: 'name',
                applyFilter: false,
            });
            Filters2DManager.applyFilters(draft.data[index], [{ name: 'shift2DX', value: { shift: shiftX } }], {
                filterIndex: activeFilterIndex,
                forceReapply: activeFilterIndex !== -1,
            });
            updateView(draft, shift2DX.domainUpdateRules);
        }
        if (shiftY) {
            rollbackSpectrumByFilter(draft, {
                key: 'shift2DY',
                searchBy: 'name',
                applyFilter: false,
            });
            Filters2DManager.applyFilters(draft.data[index], [{ name: 'shift2DY', value: { shift: shiftY } }], {
                filterIndex: activeFilterIndex,
                forceReapply: activeFilterIndex !== -1,
            });
            updateView(draft, shift2DY.domainUpdateRules);
        }
    }
}
