//action
function handleCalculateApodizationFilter(draft, action) {
    const activeSpectrum = getActiveSpectrum(draft);
    if (!activeSpectrum || !draft.tempData) {
        return;
    }
    const index = activeSpectrum.index;
    const { livePreview, options, tempRollback } = action.payload;
    if (livePreview) {
        const datum = draft.data[index];
        if (!isSpectrum1D(datum)) {
            return;
        }
        const spectrum = structuredClone(current(draft).tempData[index]);
        if (!tempRollback) {
            apodization.apply(spectrum, options);
        }
        else {
            const index = datum.filters.findIndex((filter) => filter.name === 'apodization');
            for (const filter of datum.filters.slice(index)) {
                delete filter.error;
                if (!filter.enabled) {
                    continue;
                }
                try {
                    const filterOptions = filter.name === 'apodization' ? options : filter.value;
                    Filters1D[filter.name].apply(spectrum, filterOptions);
                }
                catch (error) {
                    filter.error = error.message;
                }
            }
        }
        const { im: newIm, re: newRe } = spectrum.data;
        datum.data.im = newIm;
        datum.data.re = newRe;
    }
    else {
        disableLivePreview(draft, apodization.name);
    }
}
